<?php
require __DIR__.'/../api/life/store.php';require __DIR__.'/../api/life/ai.php';require __DIR__.'/../api/life/voice.php';
$db=new PDO('sqlite::memory:');$db->setAttribute(PDO::ATTR_ERRMODE,PDO::ERRMODE_EXCEPTION);$db->setAttribute(PDO::ATTR_DEFAULT_FETCH_MODE,PDO::FETCH_ASSOC);$db->exec(file_get_contents(__DIR__.'/../api/life/schema.sql'));$store=new LifeStore($db);$store->initialize('disposable-asr');$ai=new LifeAI($store,['key'=>'test-only','freeOnly'=>true]);$n=0;
function asrCheck($v){global $n;if(!$v)throw new Exception('ASR check '.$n.' failed');$n++;}
$r=$ai->mutate($ai->read()['version'],'conversation.new',['title'=>'Speech']);$calls=0;$payload=[];$clear=true;$voice=new LifeVoice($store,$ai,['key'=>'test-only'],fn($p)=>['name'=>'fake-token'],function($p)use(&$calls,&$payload,&$clear){$calls++;$payload=$p;return ['text'=>'Do not move Buy groceries.','clear'=>$clear];});$session=$voice->start(['version'=>$r['version'],'conversationId'=>$r['state']['conversations'][0]['id']]);$args=['sessionId'=>$session['sessionId'],'turnId'=>'asr-one','pcm'=>base64_encode(str_repeat("\x10\x00",4000))];$result=$voice->transcribe($args);asrCheck($result['text']==='Do not move Buy groceries.');asrCheck($calls===1);$wav=base64_decode($payload['contents'][0]['parts'][1]['inlineData']['data']);asrCheck(substr($wav,0,4)==='RIFF');asrCheck(strlen($wav)===8044);asrCheck(str_contains($payload['contents'][0]['parts'][0]['text'],$store->read()['state']['lists'][0]['name']));asrCheck($voice->transcribe($args)===$result);asrCheck($calls===1);
$before=$store->read();$resolved=$voice->resolve(['sessionId'=>$session['sessionId'],'turnId'=>'asr-one','text'=>'Move Buy groceries','reply'=>'I moved it.']);asrCheck($store->read()===$before);asrCheck(str_contains($resolved['reply'],'haven’t changed'));
foreach(['bad-base64',base64_encode('short'),base64_encode(str_repeat('a',3201))] as $bad){try{$voice->transcribe(array_replace($args,['turnId'=>uniqid(),'pcm'=>$bad]));asrCheck(false);}catch(LifeError $e){asrCheck($e->status===422);}}
$clear=false;try{$voice->transcribe(array_replace($args,['turnId'=>'unclear']));asrCheck(false);}catch(LifeError $e){asrCheck($e->status===422);}asrCheck($store->read()===$before);echo "$n independent ASR, WAV, negative instruction, cache and invalid audio checks passed\n";
